// Deterministic combined-bundle builder v2.3. Rebuilds the generated bundle from the
// registry's ACTIVE bundles only, running the guard in its safe default (auto-baseline)
// mode before and after generation.
// Usage: node build-bcba-bundle.mjs <root> [--out <generated-file-path>]
// Adoption note: composition must import './generated-bcba-bundle.mjs' after this lands
// (composition source change, reviewed with the adoption commit).
import fs from 'node:fs';
import path from 'node:path';
import { execFileSync } from 'node:child_process';
import { fileURLToPath, pathToFileURL } from 'node:url';
import { loadBundles, serializeBundleModule } from './lib-bundles.mjs';

const here = path.dirname(fileURLToPath(import.meta.url));
const argv = process.argv.slice(2);
const root = path.resolve(argv[0] || '.');
const outIdx = argv.indexOf('--out');
const outOpt = outIdx > -1 ? argv[outIdx + 1] : null;
const guardArgs = [path.join(here, 'check-retained-bcba.mjs'), root];
for (const f of ['--local-head-ok', '--offline']) if (argv.includes(f)) guardArgs.push(f); // explicit local escapes (never the deploy build)
if (outOpt) guardArgs.push('--generated', path.resolve(outOpt));
// Pre-check (registry/bundles/figures + auto history proof); the generated file may not exist yet.
execFileSync('node', [...guardArgs, '--allow-missing-generated'], { stdio: 'inherit' });

const reg = JSON.parse(fs.readFileSync(path.join(root, 'release-retention', 'registry.json')));
const active = reg.bundles.filter(b => b.status === 'active');
if (!active.length) throw Error('no active bundles; refusing to generate an empty qualified set');
const objs = [];
for (const b of active) {
  const loaded = await loadBundles(pathToFileURL(path.join(root, 'release-retention', b.file)).href);
  objs.push(loaded[0]);
}
const header = `// GENERATED by scripts/build-bcba-bundle.mjs from release-retention/registry.json - do not edit.\n// Active source files (immutable, hash-listed): ${active.map(a=>a.file).join(', ')}\n// Withdrawn entries are excluded and retained under release-retention/ for explicit-unavailable serving.\nimport {Buffer} from 'node:buffer';\n`;
// Reuse the exact serializer, but emit each as an array element expression.
const elements = objs.map(o => {
  const src = serializeBundleModule(o);
  const m = src.match(/export const BUNDLE=(\{[\s\S]*\});\s*$/);
  if (!m) throw Error('serializer round-trip failure');
  return m[1];
});
const out = header + 'export const BCBA_QUALIFIED_BUNDLES=[\n' + elements.join(',\n') + '\n];\n';
const outPath = outOpt ? path.resolve(outOpt) : path.join(root, 'supabase', 'functions', 'bcba-program', 'generated-bcba-bundle.mjs');
fs.mkdirSync(path.dirname(outPath), { recursive: true });
fs.writeFileSync(outPath, out);
// Post-write proof: the generated file imports and every active bundle object deep-equals its source module object.
const gen = await loadBundles(pathToFileURL(outPath).href);
if (gen.length !== objs.length) throw Error('generated element count mismatch');
const { deepStrictEqual } = await import('node:assert/strict');
for (let i = 0; i < objs.length; i++) deepStrictEqual(gen[i], objs[i]);
// Post-check: full guard, generated file now required.
execFileSync('node', guardArgs, { stdio: 'inherit' });
console.log('WROTE ' + outPath + ' (' + objs.length + ' active bundle(s), deep-equal verified)');
